          '双向的物种交换从此开始：葡萄、苜蓿、石榴、胡桃沿他走过的路东来，汗血马改写了汉朝的马政；丝绸、漆器、铸铁技术西去。此后一千多年，这条横贯欧亚的道路上走过僧侣、商队、使节与军队——两千多年后，德国地理学家李希霍芬给它起名「丝绸之路」。',
