          '744 年洛阳，李白四十四岁，刚被放还；杜甫三十三岁，尚未成名。中国文学史上最著名的相遇发生了。闻一多说这是「太阳和月亮的相碰」。此后两人同游梁宋、齐鲁，「醉眠秋共被，携手日同行」——杜甫记下这句时是幸福，回头看时是诀别。两人此后再未重逢。',
