          '1414 年，榜葛剌（孟加拉）使团随船入贡一头长颈鹿，中国人认定这就是瑞兽「麒麟」，次年东非麻林国又直接进献一头。明成祖命画工绘图、翰林作颂，举国轰动。一头来自东非草原的动物，成了「四夷宾服」的政治证明——郑和带回的不只是物种，是一个被重新想象过的世界图景。',
          '然而航线的尽头暴露了航行的性质：七下西洋没有建立一处据点，没有开辟一条持续贸易线，所有交换都嵌在「朝贡—赏赐」的礼制框架里。史载赏赐所费以百万计，回航的香料苏木又被折成官员俸禄，搞得怨声载道。远航越盛大，国库越吃紧——这为日后的转向埋好了引线。',
