          '今天，南京有宝船厂遗址，太仓有刘家港遗迹，肯尼亚帕泰岛上据载仍有自称船队后裔的居民；在马来西亚与印尼，「三宝庙」香火不断——这位在故国被遗忘的宦官，在东南亚被当作神明供奉。一个失败事业的开创者，在别处收获了最长的纪念。',
          '郑和的故事常被讲成「中国错过大航海」的寓言，但更准确的读法是：他证明了这个帝国完全有能力组织世界级的远洋行动，问题只在行动为谁服务。当航路的终点是万国来朝而非万国通商，是礼仪而非利润，再庞大的舰队，也只是一场昂贵的巡游。',
