          '秦王读罢，立即废除逐客令，派人把他追回。此后二十余年，李斯参与兼并六国的全部谋划；前 221 年天下一统，他先任廷尉，后拜丞相——一个上蔡小吏，靠一篇政论加三十年经营，站到了帝国第二人的位置。',
          '值得把《谏逐客书》与李斯的一生放在一起读：它论证人才不问出身、器物不问国籍，开放得近乎激进——而写它的人，日后亲手起草了对思想的封禁令。同一个人身上的这条裂缝，是理解李斯的全部钥匙。',
