          '狱中李斯上书自辩，历数辅佐先帝、统一天下诸般功绩以求二世省视，信却被赵高扣下。前 208 年七月，他被判「具五刑」，腰斩于咸阳闹市，夷三族。刑场上便有了那句临终之叹：牵黄犬、出东门、逐狡兔。史家让这个结尾与当年的鼠叹遥遥相对——因鼠而起的功名，以犬之不逐收场。',
          '李斯死后两年，秦亡。他参与缔造的一切——郡县、书同文、统一度量衡——却被汉朝原样继承，沿用两千年。评价他因此格外困难：确立中国政体框架的功，与开思想专制先例的过，落在同一支笔下，谁也抹不掉谁。',
