          '这次出差还附带一桩私事的回声：卓王孙听闻女婿成了天子的使者，终于觉得这门婚事体面，感叹把女儿嫁给司马长卿太晚，分给女儿的财产与儿子均等。势利与亲情在同一份对账单上合而为一——汉代社会的人情冷暖，这段记载比任何道德文章都诚实。',
          '晚年相如免官，闲居茂陵。某日武帝想起他，派人去取他的全部著作；到时人已死，家中无书。其妻答：长卿临终写了一卷书，叮嘱有使者来求书就献上——那是劝武帝行封禅大典的《封禅文》。连遗作都提前算准了收件人。他身后，「赋圣」之名与「劝百讽一」的批评一起流传；鲁迅在《汉文学史纲要》里的判词最为干脆：武帝时文人，赋莫若司马相如，文莫若司马迁。',
