          '蔡伦字敬仲，桂阳郡耒阳（今湖南耒阳）人，据载出身冶铁世家，约在明帝永平末年入宫，章帝时为小黄门，和帝即位后升中常侍，得以参与机要。《后汉书》给他的评语是「有才学，尽心敦慎，数犯严颜，匡弼得失」——一个敢当廷纠正皇帝过失的宦官，历代罕见。',
