          '他的相貌成了后世雕像的母题：扁平的鼻子、凸出的眼睛，常年赤脚，一件旧斗篷穿四季。喜剧家阿里斯托芬在《云》里把他演成吊在篮子里观察天空的怪人——嘲讽他，也等于替他做了全民广告。就是这样一位丑陋的赤脚汉，让雅典的年轻人放下健身与社交，跟着他在市场上追问。',
          '他并不只是嘴上功夫。作为重装步兵，他参加过波提狄亚、德利乌姆等战役；柏拉图《会饮篇》记载，他在波提狄亚阵前救过阿尔基比亚德斯的命，败退时步履镇定。一个把「什么是勇敢」问遍全城的人，自己先在战场上示范过答案。',
