          '柏拉图不是只会画图纸的人。他三次渡海去叙拉古，试图把新僭主狄奥尼修二世教育成「哲学王」，结果卷入宫廷倾轧，据载一度险些被卖为奴，挚友狄翁后来更死于政变。三局全败。晚年他退而写《法义》，把「哲人王」的激进方案换成混合政体与法治——一位理想主义者向现实缴纳的学费。',
