          '后世对他的评价两极。凯撒三十多岁时在他的雕像前流泪：同龄的亚历山大已征服世界；近代史家则细数另一面——底比斯被夷平时的死难者、被卖为奴的推罗人、死在归途沙漠里的士兵。他是军事史上未尝败绩的天才，也是把「征服」当方法论、始终没学会「统治」的人。世界可以被打穿——他从不曾证明它可以被治理。',
