          '这份从容有家底撑腰：新王国初期的扩张已把周边打服，她只需守成。但她守得极稳——登基之初平定过努比亚的小规模叛乱，军权始终在握；图特摩斯三世则在军中长大，悄悄攒着他日后那十七场远征。',
