          '伊斯兰世界则始终记得他是「首席长老」：波斯与中亚的医学校沿他的体系运转数百年，乌尔都语与波斯语的医书长期以《医典》为纲。他的陵墓几经重修，如今是哈马丹最显眼的建筑之一，塔下是图书馆与博物馆。',
          '2005 年起，联合国教科文组织颁发以他命名的「伊本·西那奖」，表彰科学伦理领域的成就——一个把医疗当作技艺与道德双重实践的古人，在五百年后仍被用来命名「科学家该怎么做事」。知识从不属于安稳的地方；它属于白天行医、晚上写作的人。',
