          '欧洲人由此把「按固定步骤计算」叫作 algorism，最终演成 algorithm。一种计算方法的通用名，竟是中世纪拉丁抄写员的一次误读。这位花剌子模人从此在每种编程语言里隐性署名。',
          '印度数字的西传也经他之手定型：零、位值制、竖式运算——这套系统后来由比萨的斐波那契在 1202 年的《计算之书》带进商人阶层，欧洲的算术基础就此更新。从他的书页到今天的银行账本与处理器，线索没有断过。',
