          '其三，实测大地。马蒙哈里发时代，天文团队在美索不达米亚的辛贾尔平原实测子午线一度之长，折算约 111.8 公里——与今日数值惊人接近。这是人类历史上少数几次以国家之力测量地球的尝试之一，花剌子米所在的智慧宫是组织者（他本人在其中的角色，据载不详）。',
          '把这三件事放在一起看，他的特征就清楚了：他不是横空出世的天才，而是把印度、希腊、波斯三个文明的知识整理成「可用的体系」的人。在知识史上，整理本身就是发明。',
