          '他没有留下名言，没有雕像式的传奇，甚至没有确切的生平。马德里大学校园里立着他的雕像，是 20 世纪后人补的想象像——一个连面孔都要靠猜的古人。',
          '但这恰恰是最彻底的胜利：大多数人不知道他叫什么，却每天都在用他的遗产——解方程是 algebra，写代码是 algorithm，连手机上的每个数字都是他定型的写法。有些人的名字消失了，有些人的名字变成了所有名词。',
