          '他的记录有商人的精确癖好：城市讲人口、税收、物产、桥梁数。这常常夸张，却总在方向上正确。杭州被他称作「行在」——世界最繁华之城，有一万两千座桥，人民的举止温文有礼。数字夸大，繁华不假：宋人自己写的《梦粱录》可为旁证。',
          '在东方待了约十七年后，机会来了：1291 年，伊儿汗国阿鲁浑汗请求娶一位蒙古公主。忽必烈选了阔阔真，波罗一家随护送团走海路——从泉州出发，十四艘船，穿南海、过爪哇、绕印度海岸至波斯。这次航行送走的不只是公主，还有欧洲人的一整套东方记忆。',
