          '同狱有一位职业写手——比萨人鲁斯蒂谦，此前的营生是给法国贵族写骑士传奇。马可口述，鲁斯蒂谦执笔，两人把一部商人的见闻录写成了传奇体：《寰宇记》（后世又称《马可·波罗行纪》或《百万》）。1299 年获释后，马可回到威尼斯，经商、娶妻、育有三女，安稳地当回了市民，1324 年去世。',
