          '流放也是他的文学生产力。这二十年间，他写了《筵席》（一部用俗语写就的知识百科式对话）、《论世界帝国》（论证普世君主制，后被教会列为禁书），以及理论要著《论俗语》——用拉丁文论证：俗语（母语）值得用于最高的文学。这在当时近乎异端：文学的最高文体，几百年只属于拉丁文。',
          '《神曲》约于 1308 年动笔，1320 年前后完成。流放者没有失去一切——他失去了故乡，换来了写作的时间与怨气。伟大的作品常常需要一个无处可去的人。',
