          '16 世纪，文人本博把但丁、彼特拉克、薄伽丘三位托斯卡纳作家确立为意大利语的标准范本——一门现代民族语言，以三个人的书为语法。从乔叟到弥尔顿，从罗西尼的歌剧字幕到今天的意大利宪法，用的都是这套语言的后裔。',
