          '1492 年 8 月 3 日，旗舰圣玛利亚与品达号、尼尼亚号从帕洛斯港出发，共 87 人。10 月 12 日凌晨，望见巴哈马的一座小岛。哥伦布上岸，举起王旗，命名圣萨尔瓦多，认定自己到了「印度的边缘」——此后他至死没有改过口，还顺手给当地居民起了个用错五百年的名字：印第安人。',
          '他们继续南下探查古巴与伊斯帕尼奥拉。圣诞夜，旗舰搁浅损毁，残木被用来筑起美洲第一个欧洲据点「纳维达德堡」，留下三十九人。1493 年 3 月，哥伦布带着黄金、鹦鹉与几名泰诺人回到西班牙，凯旋受封——欧洲与美洲的永久连接，就此建立。',
