          '1498 年第三次航行，他望见南美大陆与奥里诺科河的庞大水流，隐约意识到这可能是「另一片世界」——但他仍把权利写进自己的头衔里。1500 年，王室派波瓦迪利亚接替总督之职，以「暴政」罪名将他锁上镣铐押回西班牙。他保住了自由与头衔，从此把那副锁链留在身边——至死随身。',
