          '他留下的名字体系本身就是一场误会：印第安人（Indios）、西印度群岛，全是「找印度没找到」的化石。加勒比之外的整个美洲，则用另一种方式给他付账：几十个哥伦布纪念碑、一个哥伦布日，以及一个每年被重新争论一次的节日。',
          '2020 年以来，从美国到拉美，多座哥伦布雕像被推倒，他由「发现者」重读为「殖民灾难的开端」。两种叙事都立得住：他没有「发现」一片住着数千万人的大陆——他连接了它，而连接的方式，是帆船与天花。评价一个连接者，从来要同时数清楚两边发生的事。',
