          '故事的框架简单到荒唐：拉曼却的一个穷乡绅读骑士小说读疯了，自封游侠骑士，骑瘦马、带农桑丘出门「锄强扶弱」——向风车冲锋，把羊群当大军，把客栈当城堡。表面上，这是对骑士文学的总清算：过时的理想主义撞上冰冷现实，一撞就散。但读下去会发现另一层：堂吉诃德疯，可他所在的世界更疯——他没有分清幻想与现实，而世界分不清正义与利润。',
          '它成为「第一部现代小说」的理由正在这里：人物会变（桑丘在旅途里渐渐染上主人的理想），视角互相塑造，读者无法安稳地站队。塞万提斯写作时绝没想到「现代」二字——他只是把一个时代所有的破绽，写进了一个瘦马的行程里。',
