          '1891 年深秋，二十四岁的玛丽亚登上开往巴黎的火车。她在拉丁区租下一间阁楼，冬天冷得把椅子压在被子上取暖，常常只以面包和茶果腹，晕倒在图书馆是常事。但两年里她拿下物理、数学两个学位，物理名次第一。1894 年，她在为一个物理学会做磁学研究时遇到了皮埃尔·居里——次年成婚，婚礼上没有戒指，只有两辆自行车。',
