          '长年的辐射早已写进她的身体：1934 年，她死于再生障碍性贫血，验尸报告称骨髓「没有反应」——像被辐射彻底用旧了。她的实验笔记至今存放在铅盒里，查阅需签免责书、穿防护服，放射性还要持续一千五百年。1995 年，她的遗体迁入巴黎先贤祠——第一位凭自身成就入祠的女性。墓碑上与皮埃尔并排，正如她坚持的那样：科学讲的是事物，不是个人。',
