          '爱迪生笃信直流：电压低、电流大、损耗随距离猛增，每隔几公里就得建一座电站——城市可以覆盖，广袤腹地没戏。特斯拉手里的王牌是多相交流：借助变压器，电压可以升到极高再远距离输送，损耗极小，到了用户端再降下来。1888 年，实业家威斯汀豪斯买下特斯拉的交流专利体系——棋盘上从此有了第三个、也是最终落子的玩家。',
