          '裁决来自两件大事。1893 年芝加哥世博会，西屋系统以远低的报价点亮十万盏灯，数千万观众亲眼看见交流电点亮一座城。1895 年，尼亚加拉瀑布水电站采用特斯拉的多相交流系统，电力输往四十公里外的布法罗——远距离输电自此成为现实。物理赢了，账本也赢了：今天全世界的电网都是交流的。',
