          '1915 年回印度时，他已是侨民中的传奇。1919 年英国颁布罗拉特法无限期拘禁嫌疑人，全国抗议；阿姆利则的戴尔将军下令向集会人群开枪，官方数字三百七十九人死。甘地由此确信与殖民政府再无合作可言，1920 年发起全国不合作运动：辞职、罢课、抵制英货，土布纺车成了国货运动的图腾——他把政治运动做成了一场道德修行。',
