          '1930 年他把目标选在盐上：盐税人人可触，制盐人人可为，犯法门槛低到不可能失败。食盐进军让全国响应，据载约六万人因此入狱，殖民机器被一张张逮捕令拖到过载；1931 年总督被迫与他会谈，同年他赴伦敦参加圆桌会议，穿着缠腰布会见国王——丘吉尔讥之为「半裸的游方僧」。讥讽没有用：盐法次年即大幅放松，而「圣雄」之名传遍世界。',
