          '他对自己人同样苛刻：长子哈里拉伊一生与之决裂；晚年的禁欲「试验」在私人日记与传记中留下至今争议的内容；他把绝食当武器，有时是对殖民者，有时是对自己的追随者——要求他们自律、募捐、清除门户之见。把政治做修行的另一面，是身边人必须陪他修行。这些都不需要回避：真实的甘地比铜像的甘地有力得多。',
