          '他的方法没有随他死去。马丁·路德·金 1959 年专程赴印度取经，后来写在自传里：到印度访甘地，是理解自己抗争的必经之路；曼德拉称非暴力与和解是南非转型的遗产之一。联合国把他的生日定为国际非暴力日。「以眼还眼，只会让全世界都失明」——这句话由一位真正被刺瞎过整个时代的见证者说出，分量因此不同。',
