          '此后六个月，他的武器只有词汇与神经。就职演说「我没有什么可以奉献，有的只是热血、辛劳、眼泪与汗水」；敦刻尔克之后「我们将在海滩上战斗」；不列颠空战最紧时「从未有如此多的人，从如此少的人那里得到过如此多」。他一再游说罗斯福：驱逐舰换基地、租借法案、大西洋宪章。1941 年 6 月德国入侵苏联，这位毕生反共的贵族立刻与斯大林结盟，理由只有一句：若希特勒入侵地狱，我至少要在下院替魔鬼说句好话。',
