          '1965 年 1 月，丘吉尔以 90 岁去世，英国为他举行国葬——伦敦码头的起重机齐齐垂下吊臂，向这位「用自己的语言为战争定调的人」敬礼，灵船沿泰晤士河溯流而上。后世史家仍在为他记账：有人记下铁幕演说如何预告冷战，有人记下孟加拉与帝国；但几乎无人否认一点——1940 年夏天，当主和的声音就在隔壁房间，是他一个人把「不投降」变成了国家的决定。',
