          '龙场万山丛杂，语言不通，随从相继病倒，他反过来砍柴汲水、唱歌解闷地照顾随从。居无定所，先住山洞，后结草庵，最后自己凿了石椁躺进去：「吾惟俟命而已。」绝境逼出一个最简单的问题——如果圣人处在此地，会怎样？',
          '一夜，他忽然悟到：向外求理是错的，「圣人之道，吾性自足」。天理不在竹子里，不在书册里，就在自己心里。这不是玄谈，是一次方向反转：朱熹把世界放进书本，王阳明把书本放回心里。心学的大幕，在贵州的山洞里拉开。',
