          '晚年他提出「致良知」：良知人人本有，见父自然知孝，见孺子入井自然知恻隐——学问不是往心里装东西，而是把被私欲遮蔽的良知擦亮。学派喊出「满街都是圣人」，惊世骇俗，本意却是把成圣的资格还给每一个普通人。',
          '这套学说的锋芒在于解构权威：是非不在朱子注疏里，在自己心里。它下启泰州学派——盐丁出身的王艮执掌教席，把学问讲给樵夫、陶匠、田夫听。心学成了明代中后期最大的一次思想平权运动，也因此被正统视为洪水猛兽。',
