          '但机器内部有纪律：杀降与劫掠使节有罪，宗教事务各随其俗，商路受武装保护，站赤驿站贯通东西。同一支军队，在战场上是灾难，在征服之后是秩序——这种分裂的品格，将定义此后两个世纪的欧亚史。',
