          '她的真名没有传下来。「紫式部」是宫中称呼：取她笔下女主人公「紫姬」之「紫」，加父兄任官的「式部」之省。约 998 年她嫁给年长二十余岁的远亲藤原宣孝，三年后丈夫病亡，留下幼女。守寡的年轻母亲开始写故事，据载最初是为深闺解闷，也为了让小女儿有故事听。',
          '时代的机关在于语言：汉文是男人的公文语言，假名被轻蔑地称作「女手」，女子不得系统学习中国经典。结果千年之后回看，奠定日本文学根基的《源氏物语》《枕草子》《和泉式部日记》，全部出自宫廷女性之手——被禁止的学问，成全了被允许的文学。',
