          '它真正的前无古人在心理：光源氏与藤壶的禁忌之恋、紫姬终身无子的隐痛、浮舟投水前夜的进退两难——平安时代的书写第一次潜进人物的内心，写「没有说出的部分」。每帖以季节花木为名，帚木、夕颜、末摘花，一帖一景，像一座按时间布置的庭园。',
          '欧洲要再过约六百年才由塞万提斯确立近代小说的地位，而《源氏物语》已有完整的心理刻画、时间纵深与作者自觉。紫式部借书中人之口论物语：虚构虽写世间未有之事，善恶诸相却比正史更见真实——这是世界文学史上最早的「小说论」之一，出自十一世纪初的一位女官。',
