          '她生前就因写物语被人非议，日记里记下那些耻笑：女人写虚构故事，在当时近于失德。一千年后，《源氏物语》的抄本、译本与论文浩如烟海，研究它自成一门学问。非议她的人没有留下名字，被非议的故事活到了今天。',
