          '他不是书斋里的诗人。三十岁起他接手家族在东孟加拉的庄园，长住乡下：收租的贵族成了农民生活的观察者，此后十年写下大量短篇小说，写寡妇、佃农、船夫。用孟加拉语为普通人写作，在当时的文学版图上是一场文体革命。',
