          '分歧真实而深刻：甘地倡导手纺车运动与不合作，泰戈尔质疑以道德之名奖励穷困；甘地尊崇乡土传统，泰戈尔警惕把过去神化。两人谁也没说服谁，但谁也没有决裂，通信与论辩持续数十年——那是二十世纪非西方世界最重要的思想对话之一。',
