          '蓝图兑现得又快又狠：208 年曹操南下，刘琮举州而降，刘备败走当阳；诸葛亮主动请缨出使江东，说动孙权联刘抗曹。赤壁一把火后，刘备趁势取荆南四郡，214 年入据成都，219 年汉中之战定军山斩夏侯渊——三足鼎立，一半是打出来的，一半是《隆中对》预写好的。',
