          '他治国的底色是法治：主持制定《蜀科》，「科教严明，赏罚必信」——马谡是他器重的心腹，街亭之败照样处死，他自己上疏自贬三级；李严同为托孤重臣，因误军被废黜，朝野无话。陈寿的判词是「刑政虽峻而无怨者」：罚得让人服气，是一种罕见的执政手艺。',
