          '北伐的后勤与装备同样出自他手：木牛流马运粮，诸葛连弩「十矢俱发」，渭滨屯田作久驻之计。234 年八月病逝军中，遗命葬定军山，「因山为坟，冢足容棺，敛以时服，不须器物」；家产只有「桑八百株，薄田十五顷」——一个掌国十一年的人，留下的清单像一份清廉的自白书。',
