          '1924 年冬他应邀北上商谈和平统一，途中病重；1925 年 3 月 12 日因肝癌病逝北京，终年五十九岁。国事遗嘱核心一句：「现在革命尚未成功，凡我同志……继续努力」；家事遗嘱只有寥寥数语——书籍衣物住宅交给妻子宋庆龄，儿女已长成，望各自爱。1929 年灵柩奉安南京紫金山中山陵。',
          '他对中国真正的改变在观念层面：在他之前，皇帝倒了才算革命；在他之后，「共和国」三个字进入国家的字典——袁世凯称帝八十三天而败，张勋复辟十二天而败，退回去的尝试都不再成立。他组织能力平平、屡战屡败，绰号「孙大炮」；但国共两党、海峡两岸至今共用同一尊像、同一个「国父」或「革命先行者」的头衔——这种罕见的一致，本身就是他成功程度的度量。',
