          '她的性向两千年来聚讼不已：古代已有传闻，维多利亚时代的译者动手「净化」译文，二十世纪女性主义批评把她请回原位。其实她留下的证据足够清楚——残篇 31 写爱欲的生理震颤：耳中轰鸣、舌碎、火在皮下奔走。争论本身成了她影响力的刻度：每个时代都在她身上校准自己对爱与身份的态度。',
