          '更大的框架是唯物史观：「不是人们的意识决定人们的存在，相反，是人们的社会存在决定人们的意识。」生产力、生产关系、上层建筑的链条，把历史写成有结构的演化而非帝王将相的连载。《资本论》第二、三卷他生前未完成——恩格斯从千页手稿里整理出两卷，1885 与 1894 年先后出版。',
