          '刺客不是南方军队，而是一个把南方失败变成个人复仇剧的名演员；同一夜，其同伙持刀重伤国务卿苏厄德，未遂。四月间，150 万美国人沿铁路线目送灵车从华盛顿回到斯普林菲尔德——寒风里，人们在道口脱帽；华盛顿的送葬队列里，黑人士兵与白人并肩走过，这在战前的美国不可想象。',
