          '战功随之而来。1134年北伐收复襄汉六郡，是南宋立国后第一次大规模收复失地；1140年郾城、颍昌两役，大破金军统帅完颜宗弼赖以称雄的重甲骑兵。金军内部流传的评语是「撼山易，撼岳家军难」——一支军队最可怕的时刻，不是打胜仗，而是让对手开始怀疑战争还能不能打下去。',
