          '为什么班师？后世争论不休：一说孤军深入有被断后路之险，一说高宗与秦桧急于议和。真实的政治账本可能是三本合一：宋高宗要的是能自保的偏安，不要能北伐的猛将；秦桧要的是和议；而武将功高本身，在本朝「以文驭武」的传统里已经近似于罪。',
