          '1142年1月27日（绍兴十一年岁末），岳飞遇害于大理寺狱中，一说风波亭，年三十九；长子岳云与部将张宪同日弃市。狱中他据载留下八个字：「天日昭昭，天日昭昭」。和议按部就班地推进，他的死成了和议的投名状——一个王朝的安全焦虑，最终由最忠诚的将军买单。',
