          '她还背过一口政治黑锅：有人诬告赵明诚生前以玉壶投献金人，她惊恐之下把家中铜器悉数追献朝廷自明心迹，并写下《金石录后序》交代这批藏品的聚散始末——今天它是研究宋代收藏史与靖康流离的第一手文献。国破、家亡、夫死、物散，四件事在几年内砸在同一个人身上。',
