          '与脚本作家达·蓬特合作的三部曲，把歌剧从贵族消遣变成了社会喜剧：《费加罗的婚礼》（1786）让聪明的仆人站到戏的中心，顺手嘲讽了伯爵的特权；《唐璜》（1787）把诱惑与审判写进喜剧框架；《女人心》（1790）干脆把爱情怀疑论搬上舞台。这些剧首演时争论不断，此后两百年再没离开过全世界的歌剧院。',
          '1791年9月首演的《魔笛》用德语演唱、面向大众，裹着埃及背景讲共济会的启蒙寓言——莫扎特与脚本作者席卡内德都是共济会员。同年夏天他接到匿名委约写一部《安魂曲》，病中的他把这单生意当成了写给自己的告别。12月5日，《安魂曲》未完成，他去世，年35岁。',
