          '得意没几年，1725年他得罪贵族罗昂骑士，先被对方的仆人当街杖责，随后又被关进巴士底狱，出狱后被要求离开巴黎。他渡海去了英国——一场羞辱，却成了他一生最重要的游学：他后来的一切思想武器，几乎都在那两年里上了膛。',
