          '从此他掌握了那个时代作家的全套生存技术：文章送境外印刷、署名用假名、书信里夹密码、随时准备逃往边界。他与学者夏特莱侯爵夫人在西雷庄园隐居十五年，合力把牛顿译介进法国；1750年应邀去柏林辅佐腓特烈二世，三年后与这位「哲学王」闹翻出走——他看清了开明专制的天花板。',
