          '对手是整套法律体系。1948年国民党上台，种族隔离被一部部法律落地：《人口登记法》按肤色给全民分类，《集团住区法》划定谁能住哪，《通行证法》规定黑人出门必须携带通行证。抗议在法律框架内一次次撞墙：1952年的蔑视不公正法运动，约八千人自愿被捕入狱。',
