          '1985年，博塔总统开价：放弃暴力即可获释。曼德拉通过女儿在索韦托的万人集会上宣读回应：只有非国大获得合法地位，才谈得上谈判——个人自由不能替代组织自由。他在狱中自学阿非利卡语、研读对手的历史与法律，把看守变成可以交谈的人。27年里，他准备的是一场谈判，不是一次越狱。',
