      '1865 年 2 月 8 日，布尔诺的自然科学研究会上，一位四十三岁的修士起身宣读论文。台下四十来位听众——农民、教师、业余爱好者——听他讲了八轮豌豆杂交、两万八千株植物的计数结果。他讲完，会场安静得出奇：没有提问，没有讨论。会后他把论文寄给学会的新会长，对方回信说他「讲得不清楚」。这篇后来被称为遗传学开山之作的论文，此后三十四年，几乎无人再提。',
