          '更超前的不是结论，是方法：他用数学处理生物学数据，先设对照组、再重复验证，把「为什么」换成「多少」；连样本量都按结论的稳定性反推。这套思维要等七十年后才成为生物学的标配——孟德尔不是超前于同行，是超前于整个学科的方法论。',
