          '1900 年春天，三位植物学家——德弗里斯、科伦斯与丘歇马克——各自做杂交实验，各自撞见三比一，各自在旧文献里翻出同一个人：三十四年前，一切早已做完。「孟德尔被重新发现」从此成为科学史的成语，遗传学在这一年正式诞生。',
