          '他的人生开关是「旁观」。十几年的宫廷生涯让他看清了权力机器的内部构造：王朝如何起家、如何腐化、如何被下一拨更饿的部族取代。他在格拉纳达见过卡斯蒂利亚的「残酷者」彼得，在开罗见过瘟疫与马穆鲁克宫廷；每次落脚都收集税册、族谱与物价。他的方法论来自经验而非书斋——《历史绪论》读起来至今不旧，因为它是田野笔记。',
