          '他不是天生统帅，更像被局面推着成长的官僚型统帅：早年随军管的像会计与后勤，治军以稳著称——不赌运气，不冒进，靠财政、盟约与耐心把优势一点点滚大。哈丁之前，他做了整整两年的外交与军事准备：断交、挑衅、诱敌，每一步都写在计划里。好运气只留给把功课做完的人。',
