          '世宗李裪 1397 年生于汉阳，太宗第三子。按宗法轮不到他：长兄放浪被废，次兄自请让位，1418 年，二十一岁的他以世子身份接掌王位；太宗让位后仍以军权监护数年，世宗的「亲政」一半是跟父亲学来的谨慎。少年时代他目疾缠身，几乎失明，靠听人诵读经史补课——他自述那段「看不见」的日子让他懂得声音与记忆的分量。后来他创制表音文字、资助天文观测，多少带着这段私人经验的痕迹。',
