          '此后五百年，谚文被士大夫冷落，却在民间牢牢扎根——女性与庶民成了它最早的守护者。1940 年《训民正音》解例本重见天日，创制原理的精密令现代语言学界惊叹：表音效率、笔画体系、字素分类自成体系。今天它是韩国官方文字，10 月 9 日是法定假日「韩字日」——一项六百年前的工程，仍在每天的报纸上运行。',
