          '对外他以文治开疆：1433 年北征女真、设六镇，把疆界推进到图们江；1419 年东征对马，打击倭寇巢穴，随后与日本室町幕府恢复通交。南拓北进之后，今日朝鲜半岛的版图轮廓，在世宗朝基本定格——文治与武功，他一样不缺。',
