          '他青年时投奔姆特瓦酋长丁吉斯瓦约，在恩甘地军中服役——那是他的军校。1820 年前后父死、族弱，他在丁吉斯瓦约支持下回祖鲁继位，带回的却不是感恩，而是一整套革命性的军事制度。',
