          '制度之外还有意象管理：白色羽饰、行军歌与战舞，被训练成心理武器——对手在开战之前先被声势压垮。夏卡懂得恐惧的经济学：让敌人未战先乱，胜利的成本就会自己降下来。',
          '这套体系让祖鲁在十余年间并吞周边上百部落，形成高度集权的军事国家——战士不入婚配、专事作战与屯垦。1810 至 1820 年代，他的胜利引发多米诺效应：败逃的部族被迫迁徙、重组、再征服，南部非洲的族群版图被整体重排——史称「姆菲卡内」（大迁徙），其代价与烈度至今仍是学界争论的沉重话题。',
