          '他晚年遇刺的引线是继承与丧亲：母死后的暴政让军中怨声载道，1828 年 9 月，异母弟丁干与姆兰加纳联手将他刺杀于庭院，临终据传留下诅咒：白人将统治这片土地。丁干继位，清洗亲兵——祖鲁由盛转衰的钟摆，从内部先动了。',
