          '国王死后，敌对的苏苏势力坐大，松迪亚塔随母流亡，辗转数国十余年，在异国学会了作战与治政。等他归来时，苏苏巫王苏曼古鲁已攻破曼丁、屠戮王室——他回去不是因为野心，是因为再没有别人能去了。',
