          '他最关键的发明是内河海军：征召渔族建造大型独木舟战舰，配弓手与石弹，控扼尼日尔河航道——沙漠里打不了骑兵，河上却可以横着走。河流即公路，舰队即首都：这套打法此前西非无人用过。',
