          '帝国在他手里完成了拼图：北控盐道，南握金矿，河网为轴，两座大城为耳目。他不再只是国王，而是收贡赋、派总督的帝国之主。1492 年，据载他在征战归途中溺亡于尼日尔河——一生与河为伴，最终与河同眠。',
