          '他深知学说的敏感性：手稿以抄本形式在学者间流传（1533 年罗马甚至有人讲解过，未遭禁止），他却拖了近三十年不肯付印。转折是年轻的德国学者雷蒂库斯：1539 年专程来拜师，1540 年先出版《初述》试探风向，1542 年终于把全书手稿带去纽伦堡付印。',
