          '出版史一波三折：督印的路德派神学家奥西安德擅自加了一篇匿名序言，称日心说「只是计算假设，并非事实」——这件未经作者同意的「防弹衣」，让书躲过了当时的查禁。哥白尼从未读到这篇序言；也许他会愤怒，也许他会庆幸：正是这层伪装，让书在罗马平安流传了七十年。',
