          '1616 年，罗马教廷把《天体运行论》列入禁书名单「待修正」，距他去世已七十三年；1835 年解禁。致敬以另一种方式抵达：第 112 号化学元素以他命名为「鿔」（Copernicium），他的头像印上过波兰钞票，华沙与克拉科夫的天文馆、大学与机场都以他命名。',
