          '1645 至 1658 年，他随剧团在外省流浪十三年：谷仓里演悲喜剧，收入不稳，常遭地方贵族刁难。正是在路上，他从配角演员转为写剧本，又从悲剧转向喜剧——他发现法国人肯为笑掏钱，而笑可以批评一切：喜剧是唯一能让观众在笑完之后想上三天的体裁。',
