          '书的美学同样是武器：提香工作室风格的木刻把解剖画成剧场——骨架倚铲沉思，肌肉标本的手臂优雅悬垂，背景是帕多瓦的山丘。这些图被翻印、抄袭、收入医书长达两百年，版画史称之为科学书籍设计的分水岭。解剖学从此不只是医学的一章，而是一门用眼睛做研究的科学。',
