          '1564 年，他辞去宫廷职务，踏上前往耶路撒冷的朝圣之路——一说是躲避宗教裁判所的死刑嫌疑（解剖人体涉渎神之说流传甚广，但证据薄弱，史家有争议），一说是学术外交。归途在希腊扎金索斯岛病逝，年仅五十岁，墓地无考。解剖学革命的旗手，死在回家的海上。',
