          '1751 年他回格拉斯哥大学任教，先教逻辑、后教道德哲学——这门课的讲义后来长成两部传世之作。1759 年《道德情操论》出版，一夜成名：斯密的核心命题是，人天生有「同情共感」，我们通过想象自己站在旁观者的位置来评判自己——这个「公正的旁观者」，是他全部道德理论的支点。',
