          '四个月后他向这位速记员求婚，坦白自己负债累累、嗜赌成性、身患癫痫，配不上她。安娜还是嫁了，婚后陪他流亡欧洲四年，期间他在轮盘赌桌上输光过她的嫁妆与旅费——她后来把这段岁月写进回忆录，语气不是控诉，是理解：他不是坏人，他是病人。',
