          '1881 年 1 月，他因肺动脉出血去世，享年五十九岁；出殡那日彼得堡万人空巷，据载数万人随灵车步行到墓地。安娜此后四十年未再嫁，把丈夫的手稿、账本与赌债凭证一一建档——世界上最难伺候的天才，遇到了最伟大的档案管理员。',
