          '在中国，他经由鲁迅一代进入：鲁迅称他是「伟大的审问者」，说他的作品让人「明白所谓罪孽与苦恼」。三十年代以来，《罪与罚》《卡拉马佐夫兄弟》的译本不断重印——中国现代文学对灵魂深度的自觉，从他这里借过火种。',
