          '1784 年他写下启蒙运动的定义文：启蒙是人类走出自己造成的不成熟状态，口号是「敢于运用你自己的理智」。他同时给理性划界：为信仰留出的空间，只余下道德——这既是对教会权威的釜底抽薪，也是对狂热的预防针。',
          '1795 年，七十岁的他出版《论永久和平》，设计共和制国家缔结和平联盟、废除常备军与秘密条约的蓝图——这份文件被后世视为国际联盟与联合国的哲学先稿。一个从没出过远门的人，为整个星球起草了和平方案，而且条款精确到可以辩论。',
