          '生活的账面则单调到极致：终身未婚，两度求婚皆犹豫错过；吃饭讲究，每天只此一餐招待客人；写作到深夜十二点半准时熄灯。健康靠作息维持，晚年体弱仍坚持授课到 1796 年。他把一生过成了一份自我实验的报告：证明一个人不靠任何外部事件，也能抵达思想的极限——传记作家们为此叫苦不迭，因为实在没有故事可写。',
