          '考古学为叙事补上了关键的实物注脚：1993 年发现的但丘石碑上，「大卫家」（bytdwd）字样清晰可读——这是大卫王朝之名首次出现在圣经之外的铭文中。不过十世纪时耶路撒冷的城址规模，学界仍有激烈分歧：经文与石头各自说了部分真话，中间的空隙，正是考古学家与历史学家仍在争论的现场。考古学家至今仍在争论大卫王朝的实际规模：耶路撒冷的「大卫城」遗址与但丘石碑上「大卫之家」的铭文，是少数几处直接的实物证据。传奇与史实在他身上格外难分——这本身已成圣经考古学最大的战场之一，而每一季新出土的陶片与城墙，都可能把这位牧童国王再往史实里挪近一步。',
