          '1944 年，病体支离的罗斯福第四次连任——此前他已确诊心衰，医生私下说他最多再撑一年。1945 年 2 月，他抱病赴雅尔塔与丘吉尔、斯大林划分战后格局：联合国框架、德国分区、苏联对日参战——两个月后，4 月 12 日，他在佐治亚温泉画肖像时突发脑溢血去世，距德国投降不到一个月。',
          '死讯传出时，据说白宫接到的第一个反应是一片死寂，随后有人痛哭——对大多数美国人来说，这个声音伴随了他们的整个成年。副总统杜鲁门接任，三周内德国投降，四个月原子弹落下，九月战争结束：罗斯福起草的胜利，由继任者签收。',
          '1951 年生效的宪法第 22 修正案明确规定总统最多两任——针对的正是他连任四届的先例。一个人用十二年塑造了制度，制度随后用一条修正案保证再也不会有第二个他：这是对美国政治最工整的注脚。',
