          '新政留下的遗产遍布今天的美国生活：社保支票、联邦存款保险、证券监管、最低工资、田纳西河谷的水坝与电网——美国人每天接触的政府，一半是罗斯福时代的建筑。自由派的「大政府」与他互为镜像，保守派骂了他九十年，也没能拆掉这些地基。',
          '国际层面，联合国宪章在旧金山签字时他已去世六周，但安理会五常结构、布雷顿森林体系与战后秩序的蓝图，都是雅尔塔会议桌上的笔迹。罗斯福的外交遗产是一条至今运行的轨道：美国作为体系的设计者与担保人。',
          '他给美国人的最后遗产是态度：面对萧条与战争，先管理恐惧，再解决问题。华盛顿纪念池畔他座像的轮椅并不显眼——正如他当年精心掩饰的那样；但每个读到其生平的人都会明白：这个人真正站立的部分，从来不在腿上。',
