          '哥本哈根诠释至今是量子力学教科书的标准讲法（尽管「多世界」等竞争诠释始终存在），互补原理溢出物理学，成为二十世纪思想史的一部分。1962 年玻尔去世，遗留在书房黑板上的图，是他最后一次推演爱因斯坦光箱实验——争论到他生命的最后一个笔画。',
