          '玻尔一生没有得到与贡献完全相称的世俗掌声——相对论的影子太长。但物理学界的共识朴素而坚定：没有玻尔，量子力学不会长成一门完整的科学；没有他搭的辩论场，量子革命可能只是几篇各自孤独的论文。他证明了科学的最优算法是：把最锋利的对手，变成最亲密的同僚。',
