          '薛定谔 1887 年生于维也纳，父亲经营油布厂却酷爱植物学与意大利文艺，每天与儿子一起用显微镜看世界；母亲是化学教授之女。他的中学时代是维也纳文化的黄金尾巴：克里姆特在画画，马勒在指挥，弗洛伊德在看病——一座为感官与思想同时纵欲的城市。',
          '他在维也纳大学师从玻尔兹曼的学生哈斯诺尔，深受统计力学传统浸染。一战中他作为奥匈炮兵军官在意大利前线服役，据载曾在炮火间隙演算。战后维也纳物资匮乏，他辗转到苏黎世任教——正是在苏黎世，三十八岁的他完成了那个方程。',
