          '历史开了个玩笑：这只反串的猫成了量子力学最著名的代言人，被印上 T 恤、写进小说、命名数据库与宠物用品店。而薛定谔真正的立场——量子力学需要修正、测量问题并未解决——恰恰是今天量子测量理论仍在认真研究的课题。他质疑的那道裂缝，至今还在。',
