          '1836 年，一家出版社请他为滑稽画配文字，他没有按套路交图注，而是写出了连载小说《匹克威克外传》。每月一期，第二期销量翻了四倍，全国疯抢——二十世纪之前的「追更」文化，从狄更斯开始。',
