          '文学界为此分裂：有人痛惜大师「自毁」，有人视之为欧洲最大的道德事件。他后来仍写出《复活》——一部把批判对准整个司法与土地制度的小说，以及大量政论。他的「勿以暴力抗恶」思想漂洋过海：在南非的年轻律师甘地与他通信，称他为老师，二人通信直到托尔斯泰去世——这条思想线后来通向了印度的非暴力独立。',
