          '真正的考验接踵而至。1673 年，吴三桂等三藩起兵，半个中国烽火，二十岁的康熙力排撤藩争议，以八年苦战平定三藩；1683 年，施琅攻取台湾，郑氏归降——清朝的统治第一次完全覆盖汉地与海洋。这两仗打完，这个异族王朝才算在中国站稳了。',
