          '文字狱在其治下已现端倪，迁界禁海令则让东南沿海付出了惨痛代价。但盖棺而论，他接手的是一个危机四伏的年轻王朝，交出的是一个版图空前、秩序稳定的成熟帝国——乾隆盛世的地基、今天中国疆域的骨架，都有他这六十一年的浇筑。他的庙号是「圣祖」，对一个异族王朝的开国之祖级人物而言，这个字不算夸张。他批阅奏章用朱砂，测量国土用西洋仪器，笼络汉人士大夫用科举——三件工具合起来，就是清帝国二百六十八年的治理说明书。',
