          '他治下最大的艺术事件是佛像的诞生。此前佛教艺术只用足迹、法轮与菩提树暗示佛陀；在希腊化雕塑传统深厚的犍陀罗，工匠开始照太阳神阿波罗的样子为佛陀造像——希腊式鼻梁与卷发，披着僧衣，这就是犍陀罗艺术。同一时期，恒河边的秣菟罗风格同步成熟。佛像一经出现就不可逆：它顺着丝路进入西域、敦煌、云冈、龙门，最终抵达朝鲜与日本。今天东亚所有的大佛，原型都在迦腻色伽的帝国里。',
