          '他的帝国是纯粹的贸易国家，成也丝路、衰也丝路：三世纪萨珊波斯崛起切断西段商路，贵霜迅速碎裂为各城邦。佛教没有跟着帝国一起碎——它已经离开政治母体，沿着商路自行传播。帝国护法的效果，恰恰是让佛法不再需要帝国。',
