      '610 年，麦加城外的希拉山洞。四十岁的商人穆罕默德常年独上此山静思，这一次他告诉家人：有人命令他「诵读」——他答「我不会诵读」，那声音便把话压进他心里。此后二十二年，这些启示被逐句记录，成为《古兰经》；而阿拉伯半岛，也第一次被同一个词——真主独一——统一在一个秩序之下。',
