      '1979 年 2 月 1 日，一架波音 747 降落在德黑兰机场，年近八旬的老教士霍梅尼走下舷梯——迎接他的，是据载数百万人的欢迎人潮。此前十五年，他辗转土耳其、伊拉克与法国流亡；此前数月，巴列维国王刚刚逃离伊朗。这位以流亡者身份回国的阿亚图拉，将在一年之内建立一个此前从未存在过的政体：由教法学家监护的伊斯兰共和国。什叶派一千三百年的传统里，教士从不出仕；霍梅尼改写了这条铁律。',
