          '1941 年他出版首部著作，揭示秘密社会的使命观；此后的讲席与著述塑造了一代学生。真正让他走向政治的是 1963 年：巴列维国王推行「白色革命」（土地改革、妇女投票权等），并给美军人员治外法权——霍梅尼在库姆公开抨击国王，被捕引发全国骚乱，他一夜之间成为反对派的精神领袖。',
