          '1979 年 1 月 16 日国王出走，2 月 1 日霍梅尼回国；4 月 1 日公投以压倒多数确立伊斯兰共和国——宪法的顶层设计写明法基赫最高监护。11 月，学生占领美国大使馆扣留人质四百四十四天，革命从内部事务变成对西方秩序的正面冲撞。',
