          '1988 年停火前夕，监狱系统对政治犯的集体处决成为政权最深的污点，遇难者数以千计（人权组织估计数千至上万）；1989 年 2 月，他又对《撒旦诗篇》作者拉什迪发出全球追杀令——一个宗教领袖对一国之外的小说家下死刑令，把革命的影响（与争议）推到了西方世界的书房里。',
          '对内，他推行全面的伊斯兰化：酒禁、着装令、性别隔离与道德警察重塑日常；经济国有化与反美意识形态构成新国家的骨架。他所立的「法基赫监护」体制把最高权力交给终身制的最高领袖——这个制度在他死后仍在运转，是二十世纪最独特的政体发明之一。',
