          '军旅成了他真正的大学：1948 年巴勒斯坦战争中，他在被围困的法卢贾据点坚守数月，亲眼见证阿拉伯军队装备的落后与指挥层的腐败——军官团的怨气由此积成。战后他与同志们秘密组织「自由军官组织」，暗号「医师」，目标只有一个：推翻与英国签有盟约的埃及王室。',
