          '1900 年他来到巴黎，头几年穷得与诗人雅各布轮流睡一张床、共享一件大衣。这个阶段的「蓝色时期」画盲人与乞丐，整幅画浸在忧郁的蓝里；1904 年定居蒙马特高地后画风转暖，进入「玫瑰时期」，画马戏团杂技演员与粉色的少年——这一时期的《拿烟斗的男孩》在 2004 年拍出逾一亿美元，是他早期市场的注脚。',
