          '《格尔尼卡》在巴黎世博会展出时，与苏俄馆、德国馆隔街对峙——展馆本身就是意识形态的战场。此后这幅画开始了漫长的流亡：毕加索拒绝让它进入佛朗哥统治的西班牙，立下遗嘱——西班牙重获民主之日，就是它回家之时。1981 年，画家去世六年、佛朗哥死后六年，《格尔尼卡》回到马德里，沿途是漫长的人链与欢呼。',
