          '在乔凡尼·贝利尼门下，他与兄长结识了天才师兄乔尔乔内。两人合作的名作让雇主分不清谁画了哪一笔——据记载此事惹恼了老师。乔尔乔内带来的新东西是革命性的：画人物不靠轮廓，靠色彩与光影的呼吸；风景不只是背景，是情绪本身。1510 年乔尔乔内死于瘟疫，年方三十三，把这条新路线留给了提香。',
