          '现代天文学的诸多工具仍以他为名：开普勒空间望远镜 2009 年升空，用凌星法找系外行星，几年里确认两千七百多颗新行星——人类寻找「第二地球」的探索，用的正是一个四百年前被打成异端时代遗孤的人的方法论：相信数据，胜过相信审美。',
