          '数学家拉格朗日在旁目睹了这一切，留下那句传世判词：砍下这颗头颅只需一瞬，也许一百年都未必再能长出一颗同样的头颅。两年后，法国政府公开承认错判并向遗孀致歉——道歉信写得体面，可惜那颗头颅已经无法归还。',
