          '1680 年西瓦吉病逝，五十三岁。他留下的不是一个大帝国——马拉塔当时只控制德干西部——而是一套打法、一个合法性神话与一支军队。他的儿子桑巴吉继续抗衡莫卧儿，虽被俘处死，马拉塔人反而越战越勇。',
          '奥朗则布晚年在德干打了二十多年，帝国的财政与军力被拖垮在山地里。马拉塔人靠游击战熬死了这位在位四十九年的皇帝——此后莫卧儿迅速衰落，而马拉塔联盟将成为十八世纪印度的实际主人。',
