          '民族主义时代，西瓦吉被重新加冕：提拉克为他办大规模纪念节，把「查特拉帕蒂」变成反抗殖民的旗帜；甘地、尼赫鲁、萨瓦尔卡都引用过他。今天孟买的地标火车站以「贾特拉帕蒂·西瓦吉」命名，印度海军的多艘军舰也沿用他的名字。',
          '他也留下争议：现代史家争论他是否是「印度教民族主义者」——他确实以印度教王权立国，却也雇用穆斯林将领、保护清真寺。这种多义性恰恰说明：他的遗产属于所有想从历史里借勇气的人。',
