          '宫廷生活被礼仪精确编码：国王用膳是公开演出，猎装、舞会、歌剧的座次都是权力文件。他让贵族的野心从领地转向包厢——「在凡尔赛，人们不再是领主，而是客人」。同时，法语取代拉丁语成为欧洲外交语言，法国时尚、美食与礼仪成为全欧洲的教科书本。',
          '文艺上他同样集权：皇家科学院、歌剧院、铸造厂由国家供养；莫里哀的喜剧、拉辛的悲剧在国王眼皮底下上演。艺术第一次被国家编制——「太阳王」的光环之下，是一个把文化也编入官僚体系的现代国家雏形。',
