          '他的对外政策也留下黑色一页：1685 年废除「南特敕令」，数十万胡格诺新教徒（其中大量工匠与商人）流亡荷兰、普鲁士与英格兰——对手国家的手工业与金融业被法国亲手输送了一遍人才。史家普遍视其为路易十四最愚蠢的一项决定。',
